<?php
declare(strict_types=1);namespace Atlas\Platform\PatientResources\Rest;use Atlas\Platform\Organizations\Services\CurrentOrganizationResolver;use Atlas\Platform\PatientResources\Services\PatientResourceVariantService;use InvalidArgumentException;use RuntimeException;use WP_Error;use WP_REST_Request;use WP_REST_Response;final class PatientResourceController{public function __construct(private PatientResourceVariantService $service,private CurrentOrganizationResolver $organizations){}public function permission():bool{return is_user_logged_in()&&current_user_can('atlas_manage_branding');}public function save(WP_REST_Request $request):WP_REST_Response|WP_Error{$org=$this->organizations->resolveForUser(get_current_user_id());if($org===null){return new WP_Error('atlas_organization_context_unavailable',__('A single active organization is required.','atlas-platform'),['status'=>409]);}$custom=$request->get_param('customizations');if(!is_array($custom)){return new WP_Error('atlas_patient_variant_invalid',__('Customizations must be an object.','atlas-platform'),['status'=>400]);}$key=sanitize_text_field((string)($request->get_header('Idempotency-Key')?:$request->get_param('idempotency_key')));try{$variant=$this->service->save($org->id,(string)$request->get_param('id'),$custom,$key,get_current_user_id());return $variant===null?new WP_Error('atlas_patient_resource_not_found',__('The patient resource was not found or is not accessible.','atlas-platform'),['status'=>404]):new WP_REST_Response(['variant'=>$variant->toArray()],201);}catch(InvalidArgumentException $e){return new WP_Error('atlas_patient_variant_invalid',$e->getMessage(),['status'=>400]);}catch(RuntimeException){return new WP_Error('atlas_patient_variant_conflict',__('The variant could not be saved.','atlas-platform'),['status'=>409]);}}}
